  "Beginner": "\u0645\u0628\u062A\u062F\u0626",
  "Quantum computing": "\u0627\u0644\u062D\u0648\u0633\u0628\u0629 \u0627\u0644\u0643\u0645\u064A\u0629",
  "Generating study material...": "\u062C\u0627\u0631\u064D \u0625\u0646\u0634\u0627\u0621 \u0645\u0627\u062F\u0629 \u0627\u0644\u062F\u0631\u0627\u0633\u0629...",
