  "Generate": "\u0625\u0646\u0634\u0627\u0621",
  "Team Workspace": "\u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644 \u0627\u0644\u0641\u0631\u064A\u0642",
  "Build websites together": "\u0627\u0628\u0646\u0648\u0627 \u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u0645\u0639\u0627\u064B",
  "Secure roles, invitations and shared projects. Pro supports 3 seats; Business supports 10 seats.": "\u0623\u062F\u0648\u0627\u0631 \u0648\u062F\u0639\u0648\u0627\u062A \u0648\u0645\u0634\u0627\u0631\u064A\u0639 \u0645\u0634\u062A\u0631\u0643\u0629 \u0622\u0645\u0646\u0629. \u062A\u062F\u0639\u0645 Pro \u062B\u0644\u0627\u062B\u0629 \u0623\u0639\u0636\u0627\u0621 \u0648Business \u0639\u0634\u0631\u0629 \u0623\u0639\u0636\u0627\u0621.",
  "Paste a team invitation token or open an invitation link": "\u0623\u0644\u0635\u0642 \u0631\u0645\u0632 \u062F\u0639\u0648\u0629 \u0627\u0644\u0641\u0631\u064A\u0642 \u0623\u0648 \u0627\u0641\u062A\u062D \u0631\u0627\u0628\u0637 \u0627\u0644\u062F\u0639\u0648\u0629",
  "Your teams": "\u0641\u0631\u0642\u0643",
  "No team workspaces yet.": "\u0644\u0627 \u062A\u0648\u062C\u062F \u0645\u0633\u0627\u062D\u0627\u062A \u0639\u0645\u0644 \u0644\u0644\u0641\u0631\u064A\u0642 \u0628\u0639\u062F.",
  "New workspace name": "\u0627\u0633\u0645 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u062C\u062F\u064A\u062F\u0629",
  "Create or select a team workspace to manage members and projects.": "\u0623\u0646\u0634\u0626 \u0623\u0648 \u0627\u062E\u062A\u0631 \u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644 \u0641\u0631\u064A\u0642 \u0644\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0623\u0639\u0636\u0627\u0621 \u0648\u0627\u0644\u0645\u0634\u0627\u0631\u064A\u0639.",
  "Rename workspace": "\u0625\u0639\u0627\u062F\u0629 \u062A\u0633\u0645\u064A\u0629 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644",
  "Delete workspace": "\u062D\u0630\u0641 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644",
  "Invite teammate": "\u062F\u0639\u0648\u0629 \u0632\u0645\u064A\u0644",
