  "Remove member": "\u0625\u0632\u0627\u0644\u0629 \u0639\u0636\u0648",
  "Pending invitations": "\u0627\u0644\u062F\u0639\u0648\u0627\u062A \u0627\u0644\u0645\u0639\u0644\u0642\u0629",
  "Shared projects": "\u0627\u0644\u0645\u0634\u0627\u0631\u064A\u0639 \u0627\u0644\u0645\u0634\u062A\u0631\u0643\u0629",
  "Select one of your personal projects\u2026": "\u0627\u062E\u062A\u0631 \u0623\u062D\u062F \u0645\u0634\u0627\u0631\u064A\u0639\u0643 \u0627\u0644\u0634\u062E\u0635\u064A\u0629\u2026",
  "Share project": "\u0645\u0634\u0627\u0631\u0643\u0629 \u0627\u0644\u0645\u0634\u0631\u0648\u0639",
  "Remove from workspace": "\u0625\u0632\u0627\u0644\u0629 \u0645\u0646 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644",
  "Open Website Builder from the Tools menu; this shared project will appear in the Cloud Projects selector.": "\u0627\u0641\u062A\u062D \u0645\u0646\u0634\u0626 \u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u0645\u0646 \u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0623\u062F\u0648\u0627\u062A\u061B \u0633\u064A\u0638\u0647\u0631 \u0647\u0630\u0627 \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u0645\u0634\u062A\u0631\u0643 \u0641\u064A \u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0645\u0634\u0627\u0631\u064A\u0639 \u0627\u0644\u0633\u062D\u0627\u0628\u064A\u0629.",
  "No projects shared with this workspace yet.": "\u0644\u0627 \u062A\u0648\u062C\u062F \u0645\u0634\u0627\u0631\u064A\u0639 \u0645\u0634\u062A\u0631\u0643\u0629 \u0645\u0639 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u0647\u0630\u0647 \u0628\u0639\u062F.",
  "Settings": "\u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A",
  "Manage your account, security, and preferences.": "\u0623\u062F\u0631 \u062D\u0633\u0627\u0628\u0643 \u0648\u0623\u0645\u0627\u0646\u0643 \u0648\u062A\u0641\u0636\u064A\u0644\u0627\u062A\u0643.",
