  "Continue Working": "\u0645\u062A\u0627\u0628\u0639\u0629 \u0627\u0644\u0639\u0645\u0644",
  "No drafts in progress. Start a new document and it'll show up here.": "\u0644\u0627 \u062A\u0648\u062C\u062F \u0645\u0633\u0648\u062F\u0627\u062A \u0642\u064A\u062F \u0627\u0644\u0639\u0645\u0644. \u0627\u0628\u062F\u0623 \u0645\u0633\u062A\u0646\u062F\u0627\u064B \u062C\u062F\u064A\u062F\u0627\u064B \u0648\u0633\u064A\u0638\u0647\u0631 \u0647\u0646\u0627.",
  "AI Recommendations": "\u0627\u0642\u062A\u0631\u0627\u062D\u0627\u062A \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A",
  "Recent Activity": "\u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0623\u062E\u064A\u0631",
  "No recent activity": "\u0644\u0627 \u064A\u0648\u062C\u062F \u0646\u0634\u0627\u0637 \u062D\u062F\u064A\u062B",
  "My Files": "\u0645\u0644\u0641\u0627\u062A\u064A",
  "All your generated documents, CVs, translations, chats and projects in one place.": "\u0643\u0644 \u0645\u0633\u062A\u0646\u062F\u0627\u062A\u0643 \u0648\u0633\u064A\u0631\u0643 \u0627\u0644\u0630\u0627\u062A\u064A\u0629 \u0648\u062A\u0631\u062C\u0645\u0627\u062A\u0643 \u0648\u0645\u062D\u0627\u062F\u062B\u0627\u062A\u0643 \u0648\u0645\u0634\u0627\u0631\u064A\u0639\u0643 \u0641\u064A \u0645\u0643\u0627\u0646 \u0648\u0627\u062D\u062F.",
