  "Audit": "\u0627\u0644\u062A\u062F\u0642\u064A\u0642",
  "Health": "\u0627\u0644\u062D\u0627\u0644\u0629",
  "Sync": "\u0627\u0644\u0645\u0632\u0627\u0645\u0646\u0629",
  "Live": "\u0645\u0628\u0627\u0634\u0631",
  "Launch blockers": "\u0645\u0639\u0648\u0642\u0627\u062A \u0627\u0644\u0625\u0637\u0644\u0627\u0642",
  "\u2713 No critical production blockers detected.": "\u2713 \u0644\u0645 \u064A\u062A\u0645 \u0627\u0643\u062A\u0634\u0627\u0641 \u0645\u0639\u0648\u0642\u0627\u062A \u0625\u0646\u062A\u0627\u062C \u062D\u0631\u062C\u0629.",
  "Automated launch checks": "\u0641\u062D\u0648\u0635\u0627\u062A \u0627\u0644\u0625\u0637\u0644\u0627\u0642 \u0627\u0644\u0622\u0644\u064A\u0629",
  "Publish only after the preflight items are green.": "\u0627\u0646\u0634\u0631 \u0641\u0642\u0637 \u0628\u0639\u062F \u0646\u062C\u0627\u062D \u062C\u0645\u064A\u0639 \u0641\u062D\u0648\u0635\u0627\u062A \u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0625\u0637\u0644\u0627\u0642.",
  "Quick-start onboarding": "\u0625\u0639\u062F\u0627\u062F \u0633\u0631\u064A\u0639",
  "Start from a proven page structure, then complete the production URL and cloud save.": "\u0627\u0628\u062F\u0623 \u0628\u0647\u064A\u0643\u0644 \u0635\u0641\u062D\u0629 \u0645\u062C\u0631\u0628 \u062B\u0645 \u0623\u0643\u0645\u0644 \u0631\u0627\u0628\u0637 \u0627\u0644\u0625\u0646\u062A\u0627\u062C \u0648\u0627\u0644\u062D\u0641\u0638 \u0627\u0644\u0633\u062D\u0627\u0628\u064A.",
