  "Manage subscription": "\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0627\u0634\u062A\u0631\u0627\u0643",
  "CURRENT": "\u0627\u0644\u062D\u0627\u0644\u064A",
  "Active plan": "\u0627\u0644\u062E\u0637\u0629 \u0627\u0644\u0646\u0634\u0637\u0629",
  "Manage downgrade in Stripe": "\u0625\u062F\u0627\u0631\u0629 \u062E\u0641\u0636 \u0627\u0644\u062E\u0637\u0629 \u0641\u064A Stripe",
  "Default plan": "\u0627\u0644\u062E\u0637\u0629 \u0627\u0644\u0627\u0641\u062A\u0631\u0627\u0636\u064A\u0629",
