  "Sending feedback...": "\u062C\u0627\u0631\u064D \u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0645\u0644\u0627\u062D\u0638\u0627\u062A...",
  "Thank you for your feedback!": "\u0634\u0643\u0631\u0627\u064B \u0644\u0645\u0644\u0627\u062D\u0638\u0627\u062A\u0643!",
  "Failed to send feedback. Please try again.": "\u0641\u0634\u0644 \u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0645\u0644\u0627\u062D\u0638\u0627\u062A. \u062D\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062E\u0631\u0649.",
  "Please describe the steps to reproduce": "\u064A\u0631\u062C\u0649 \u0648\u0635\u0641 \u062E\u0637\u0648\u0627\u062A \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u0645\u0634\u0643\u0644\u0629",
