  "Help me write a cover letter": "\u0633\u0627\u0639\u062F\u0646\u064A \u0641\u064A \u0643\u062A\u0627\u0628\u0629 \u062E\u0637\u0627\u0628 \u062A\u063A\u0637\u064A\u0629",
